-- Additive V5 upgrade. Existing owner, inventory, articles and queue remain authoritative.
alter table public.profiles drop constraint profiles_role_check;
alter table public.profiles add constraint profiles_role_check check(role in ('super_admin','admin','seo_manager','editor','publishing_operator','viewer'));
alter table public.profiles add column department text not null default '',add column password_change_required boolean not null default false,add column min_session_created_at timestamptz not null default '1970-01-01',add column updated_at timestamptz not null default now();
alter table public.tenant_invites drop constraint tenant_invites_role_check;
alter table public.tenant_invites add constraint tenant_invites_role_check check(role in ('admin','seo_manager','editor','publishing_operator','viewer'));
alter table public.tenant_invites add column full_name text not null default '',add column department text not null default '',add column password_change_required boolean not null default true,add column active boolean not null default true,add column expires_at timestamptz not null default now()+interval '7 days';
create table public.permissions(key text primary key,description text not null);
insert into public.permissions select k,k from unnest(array['users.create','users.read','users.update','users.disable','websites.read','websites.create','websites.update','websites.connect','articles.read','articles.read_all','articles.create','articles.edit','articles.approve','articles.seo','campaigns.view','campaigns.read_all','campaigns.create','campaigns.approve','campaigns.launch','campaigns.cancel','reports.view','reports.export','reports.share','settings.manage','tasks.manage','tasks.read','publishers.research']) k;
create table public.roles(id text primary key,description text not null,protected_role boolean not null default false);
insert into public.roles values('super_admin','Workspace owner',true),('admin','Administrator',true),('seo_manager','SEO manager',false),('editor','Assigned article editor',false),('publishing_operator','Assigned publishing operator',false),('viewer','Assigned campaign reporting user',false);
create table public.role_permissions(role_id text not null references public.roles(id),permission_key text not null references public.permissions(key),primary key(role_id,permission_key));
insert into public.role_permissions select r.id,p.key from public.roles r cross join public.permissions p where r.id in ('super_admin','admin');
insert into public.role_permissions select 'seo_manager',key from public.permissions where key in ('websites.read','websites.create','websites.update','websites.connect','articles.read','articles.read_all','articles.create','articles.edit','articles.approve','articles.seo','campaigns.view','campaigns.read_all','campaigns.create','campaigns.approve','campaigns.launch','campaigns.cancel','reports.view','reports.export','reports.share','tasks.manage','tasks.read','publishers.research');
insert into public.role_permissions select 'editor',key from public.permissions where key in ('articles.read','articles.create','articles.edit','articles.seo','tasks.read');
insert into public.role_permissions select 'publishing_operator',key from public.permissions where key in ('websites.read','articles.read','campaigns.view','campaigns.create','campaigns.launch','campaigns.cancel','reports.view','reports.export','tasks.read');
insert into public.role_permissions select 'viewer',key from public.permissions where key in ('campaigns.view','reports.view','reports.export','tasks.read');
create table public.user_permissions(tenant_id uuid not null,user_id uuid not null,permission_key text not null references public.permissions(key),allowed boolean not null,primary key(user_id,permission_key),foreign key(tenant_id,user_id) references public.profiles(tenant_id,id));
create index user_permissions_tenant_idx on public.user_permissions(tenant_id,user_id);
create function private.actor_permission(p_actor uuid,p_key text) returns boolean language sql stable set search_path='' as $$
 select coalesce((select case when p.role='super_admin' then true else coalesce((select allowed from public.user_permissions u where u.user_id=p.id and u.permission_key=p_key),exists(select 1 from public.role_permissions r where r.role_id=p.role and r.permission_key=p_key)) end from public.profiles p where p.id=p_actor and p.active and not p.password_change_required),false)
$$;
create function private.session_allowed() returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.profiles p join auth.sessions s on s.user_id=p.id and s.id::text=auth.jwt()->>'session_id' where p.id=auth.uid() and p.active and not p.password_change_required and s.created_at>=p.min_session_created_at)
$$;
create function private.has_permission(p_key text) returns boolean language sql stable security definer set search_path='' as $$ select private.session_allowed() and private.actor_permission(auth.uid(),p_key) $$;
revoke all on function private.actor_permission(uuid,text),private.session_allowed(),private.has_permission(text) from public,anon,authenticated;
grant execute on function private.actor_permission(uuid,text),private.session_allowed(),private.has_permission(text) to service_role;
grant execute on function private.session_allowed(),private.has_permission(text) to authenticated;
create or replace function private.tenant_id() returns uuid language sql stable security definer set search_path='' as $$ select tenant_id from public.profiles where id=auth.uid() and private.session_allowed() $$;
create or replace function private.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select private.has_permission('settings.manage') $$;
create function public.effective_permissions(p_actor uuid) returns text[] language sql stable set search_path='' as $$ select coalesce(array_agg(key order by key),'{}') from public.permissions where private.actor_permission(p_actor,key) $$;
create function public.validate_actor_session(p_actor uuid,p_session uuid,p_password_flow boolean default false) returns boolean language sql stable set search_path='' as $$ select exists(select 1 from public.profiles p join auth.sessions s on s.user_id=p.id where p.id=p_actor and s.id=p_session and s.created_at>=p.min_session_created_at and p.active and (p_password_flow or not p.password_change_required)) $$;
create or replace function private.on_signup() returns trigger language plpgsql security definer set search_path='' as $$
declare t uuid;inv public.tenant_invites;r text;p boolean;begin
 select * into inv from public.tenant_invites where email=lower(new.email) for update;
 if inv.id is not null then
  if inv.expires_at<now() then raise exception 'Employee invitation expired';end if;t:=inv.tenant_id;r:=inv.role;p:=r in ('admin','seo_manager','publishing_operator');delete from public.tenant_invites where id=inv.id;
 else insert into public.tenants(name) values('My publishing workspace') returning id into t;insert into public.settings(tenant_id) values(t);r:='super_admin';p:=true;end if;
 insert into public.profiles(id,tenant_id,full_name,email,role,can_publish,department,password_change_required,active) values(new.id,t,left(coalesce(nullif(inv.full_name,''),new.raw_user_meta_data->>'full_name',''),200),lower(new.email),r,p,coalesce(inv.department,''),coalesce(inv.password_change_required,false),coalesce(inv.active,true));return new;
end $$;
alter table public.articles add column original_content text,add column assigned_to uuid,add column approved_version_id uuid,add column current_version_id uuid;
alter table public.articles add column archived_at timestamptz;
alter table public.articles add foreign key(tenant_id,assigned_to) references public.profiles(tenant_id,id);
create index articles_assigned_idx on public.articles(tenant_id,assigned_to);
alter table public.campaigns add column assigned_to uuid,add column client_name text not null default '',add column project_name text not null default '',add column report_recipient text not null default '';
alter table public.campaigns add foreign key(tenant_id,assigned_to) references public.profiles(tenant_id,id);
create index campaigns_assigned_idx on public.campaigns(tenant_id,assigned_to);
alter table public.publishing_logs add column actor_id uuid references public.profiles(id);
create index publishing_logs_actor_idx on public.publishing_logs(tenant_id,actor_id,created_at desc);
create table public.tasks(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),created_by uuid not null,title text not null check(length(title) between 1 and 200),assigned_to uuid,article_id uuid,campaign_id uuid,priority text not null default 'normal' check(priority in ('low','normal','high','urgent')),status text not null default 'todo' check(status in ('todo','in_progress','waiting','completed')),notes text not null default '' check(length(notes)<=10000),due_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(tenant_id,created_by) references public.profiles(tenant_id,id),foreign key(tenant_id,assigned_to) references public.profiles(tenant_id,id),foreign key(tenant_id,article_id) references public.articles(tenant_id,id),foreign key(tenant_id,campaign_id) references public.campaigns(tenant_id,id));
create index tasks_tenant_idx on public.tasks(tenant_id,status);create index tasks_assignee_idx on public.tasks(tenant_id,assigned_to);create index tasks_article_idx on public.tasks(tenant_id,article_id);create index tasks_campaign_idx on public.tasks(tenant_id,campaign_id);create index tasks_creator_idx on public.tasks(tenant_id,created_by);
create table public.seo_article_versions(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,article_id uuid not null,created_by uuid not null,original_content text not null,optimized_content text not null,seo_data jsonb not null default '{}',provider text not null check(provider in ('legacy','manual','openai','assistant_prepared')),model text,status text not null default 'proposed' check(status in ('proposed','accepted','approved','superseded')),source_updated_at timestamptz,approved_by uuid,approved_at timestamptz,created_at timestamptz not null default now(),unique(tenant_id,article_id,id),foreign key(tenant_id,article_id) references public.articles(tenant_id,id),foreign key(tenant_id,created_by) references public.profiles(tenant_id,id),foreign key(tenant_id,approved_by) references public.profiles(tenant_id,id));
create index seo_versions_article_idx on public.seo_article_versions(tenant_id,article_id,created_at desc);create index seo_versions_creator_idx on public.seo_article_versions(tenant_id,created_by);create index seo_versions_approver_idx on public.seo_article_versions(tenant_id,approved_by);
alter table public.articles add foreign key(tenant_id,id,approved_version_id) references public.seo_article_versions(tenant_id,article_id,id);
alter table public.articles add foreign key(tenant_id,id,current_version_id) references public.seo_article_versions(tenant_id,article_id,id);
update public.articles set original_content=content where original_content is null;
insert into public.seo_article_versions(tenant_id,article_id,created_by,original_content,optimized_content,seo_data,provider,status,source_updated_at,approved_by,approved_at) select tenant_id,id,owner_id,original_content,content,jsonb_build_object('title',title,'meta_title',meta_title,'meta_description',meta_description,'slug',slug,'primary_keyword',focus_keyword,'category',category,'tags',tags),'legacy',case when status='approved' then 'approved' else 'accepted' end,updated_at,approved_by,approved_at from public.articles;
update public.articles a set approved_version_id=v.id from public.seo_article_versions v where v.article_id=a.id and v.status='approved';
update public.articles a set current_version_id=v.id from public.seo_article_versions v where v.article_id=a.id;
create function private.snapshot_article() returns trigger language plpgsql set search_path='' as $$ declare v uuid;begin
 if tg_op='INSERT' or (new.content,new.title,new.meta_title,new.meta_description,new.slug,new.focus_keyword,new.tags,new.category) is distinct from (old.content,old.title,old.meta_title,old.meta_description,old.slug,old.focus_keyword,old.tags,old.category) then
  insert into public.seo_article_versions(tenant_id,article_id,created_by,original_content,optimized_content,seo_data,provider,status,source_updated_at,approved_by,approved_at) values(new.tenant_id,new.id,new.owner_id,coalesce(new.original_content,new.content),new.content,jsonb_build_object('title',new.title,'meta_title',new.meta_title,'meta_description',new.meta_description,'slug',new.slug,'primary_keyword',new.focus_keyword,'category',new.category,'tags',new.tags),'manual',case when new.status='approved' then 'approved' else 'accepted' end,new.updated_at,new.approved_by,new.approved_at) returning id into v;
  update public.articles set current_version_id=v,approved_version_id=case when new.status='approved' then v end where id=new.id;
 end if;return new;end $$;
create trigger article_version_snapshot after insert or update of content,title,meta_title,meta_description,slug,focus_keyword,tags,category on public.articles for each row execute function private.snapshot_article();

create function private.can_read_article(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.articles a where a.id=p_id and a.archived_at is null and a.tenant_id=private.tenant_id() and ((private.has_permission('articles.read') and (a.owner_id=auth.uid() or a.assigned_to=auth.uid() or private.has_permission('articles.read_all'))) or (a.status='approved' and private.has_permission('campaigns.create')))) $$;
create function private.can_read_campaign(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.campaigns c where c.id=p_id and c.tenant_id=private.tenant_id() and private.has_permission('campaigns.view') and (private.has_permission('campaigns.read_all') or c.owner_id=auth.uid() or c.assigned_to=auth.uid())) $$;
revoke all on function private.can_read_article(uuid),private.can_read_campaign(uuid) from public,anon;grant execute on function private.can_read_article(uuid),private.can_read_campaign(uuid) to authenticated,service_role;
drop policy tenant_read on public.profiles;create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or (tenant_id=private.tenant_id() and private.has_permission('users.read')));
drop policy tenant_read on public.websites;create policy websites_read on public.websites for select to authenticated using(tenant_id=private.tenant_id() and private.has_permission('websites.read'));
drop policy tenant_read on public.articles;create policy articles_read on public.articles for select to authenticated using(private.can_read_article(id));
drop policy tenant_read on public.campaigns;create policy campaigns_read on public.campaigns for select to authenticated using(private.can_read_campaign(id));
drop policy tenant_read on public.publishing_jobs;create policy jobs_read on public.publishing_jobs for select to authenticated using(private.can_read_campaign(campaign_id));
drop policy tenant_read on public.publishing_logs;create policy logs_read on public.publishing_logs for select to authenticated using(tenant_id=private.tenant_id() and (private.has_permission('users.read') or actor_id=auth.uid() or (job_id is not null and exists(select 1 from public.publishing_jobs j where j.id=job_id and private.can_read_campaign(j.campaign_id)))));
drop policy tenant_read on public.settings;create policy settings_read on public.settings for select to authenticated using(tenant_id=private.tenant_id() and private.has_permission('settings.manage'));
alter policy image_upload on storage.objects with check(bucket_id='article-images' and (storage.foldername(name))[1]=private.tenant_id()::text and (private.has_permission('articles.create') or private.has_permission('articles.edit')));
alter policy image_delete on storage.objects using(bucket_id='article-images' and (storage.foldername(name))[1]=private.tenant_id()::text and private.has_permission('articles.edit'));

create table public.publication_reports(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,campaign_id uuid not null,generated_at timestamptz not null default now(),last_verified_at timestamptz,created_at timestamptz not null default now(),unique(campaign_id),unique(tenant_id,id),foreign key(tenant_id,campaign_id) references public.campaigns(tenant_id,id));
create index publication_reports_tenant_idx on public.publication_reports(tenant_id,campaign_id);
create table public.publication_report_items(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,report_id uuid not null,job_id uuid not null,published_url text,verification_status text not null default 'pending' check(verification_status in ('verified','pending','draft','scheduled','failed','unavailable')),verified_at timestamptz,http_status integer,page_title text,verification_details jsonb not null default '{}',check_status text not null default 'queued' check(check_status in ('queued','checking','complete')),lease_token uuid,lease_until timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(job_id),foreign key(tenant_id,report_id) references public.publication_reports(tenant_id,id),foreign key(tenant_id,job_id) references public.publishing_jobs(tenant_id,id));
create index report_items_report_idx on public.publication_report_items(tenant_id,report_id);create index report_items_verify_idx on public.publication_report_items(updated_at) where check_status in ('queued','checking');
create table public.shared_reports(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,report_id uuid not null,created_by uuid not null,token_hash text not null unique check(length(token_hash)=64),snapshot jsonb not null,expires_at timestamptz,revoked_at timestamptz,created_at timestamptz not null default now(),foreign key(tenant_id,report_id) references public.publication_reports(tenant_id,id),foreign key(tenant_id,created_by) references public.profiles(tenant_id,id));
create index shared_reports_report_idx on public.shared_reports(tenant_id,report_id);create index shared_reports_creator_idx on public.shared_reports(tenant_id,created_by);
create function private.sync_publication_report() returns trigger language plpgsql set search_path='' as $$ declare rid uuid;begin
 insert into public.publication_reports(tenant_id,campaign_id) values(new.tenant_id,new.campaign_id) on conflict(campaign_id) do update set campaign_id=excluded.campaign_id returning id into rid;
 insert into public.publication_report_items(tenant_id,report_id,job_id,published_url,verification_status,verified_at,check_status) values(new.tenant_id,rid,new.id,new.published_url,case when new.status='published' then case when new.response_info->>'verification'='public_page_verified' then 'verified' else 'pending' end when new.status='failed' then 'failed' else 'scheduled' end,case when new.status='published' and new.response_info->>'verification'='public_page_verified' then new.published_at end,case when new.status='published' and new.published_url is not null then 'queued' else 'complete' end) on conflict(job_id) do update set published_url=excluded.published_url,verification_status=excluded.verification_status,verified_at=excluded.verified_at,check_status=excluded.check_status,updated_at=now();return new;end $$;
create trigger report_from_job after insert or update of status,published_url on public.publishing_jobs for each row execute function private.sync_publication_report();
create table public.publisher_catalog(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),created_by uuid not null,domain text not null,publisher_name text not null,category text not null default '',country text not null default '',guidelines_url text not null,submission_method text not null,contribution_type text not null default 'editorial_pitch',status text not null default 'research_prospect' check(status in ('research_prospect','guidelines_verified','publisher_approved','account_connected')),evidence_summary text not null default '',last_verified_at timestamptz,website_id uuid,created_at timestamptz not null default now(),unique(tenant_id,domain),unique(tenant_id,id),foreign key(tenant_id,created_by) references public.profiles(tenant_id,id),foreign key(tenant_id,website_id) references public.websites(tenant_id,id));
create index publisher_catalog_creator_idx on public.publisher_catalog(tenant_id,created_by);create index publisher_catalog_website_idx on public.publisher_catalog(tenant_id,website_id);
create table public.publisher_metric_observations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,publisher_id uuid not null,provider text not null check(provider in ('ahrefs','moz','semrush')),metric_name text not null check(metric_name in ('domain_rating','spam_score','domain_authority','estimated_organic_traffic')),metric_value numeric,observed_at timestamptz not null,verification text not null check(verification in ('provider_verified','unknown','failed')),evidence_reference text not null,created_at timestamptz not null default now(),foreign key(tenant_id,publisher_id) references public.publisher_catalog(tenant_id,id));
create index publisher_metrics_idx on public.publisher_metric_observations(tenant_id,publisher_id,metric_name,observed_at desc);
create table public.smoke_test_runs(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,initiated_by uuid not null,article_id uuid not null,campaign_id uuid,target_website_id uuid,status text not null check(status in ('preflight','blocked','awaiting_approval','scheduled','running','passed','failed')),published_url text,started_at timestamptz not null default now(),completed_at timestamptz,created_at timestamptz not null default now(),unique(tenant_id,id),foreign key(tenant_id,initiated_by) references public.profiles(tenant_id,id),foreign key(tenant_id,article_id) references public.articles(tenant_id,id),foreign key(tenant_id,campaign_id) references public.campaigns(tenant_id,id),foreign key(tenant_id,target_website_id) references public.websites(tenant_id,id));
create index smoke_article_idx on public.smoke_test_runs(tenant_id,article_id);create index smoke_campaign_idx on public.smoke_test_runs(tenant_id,campaign_id);create index smoke_website_idx on public.smoke_test_runs(tenant_id,target_website_id);create index smoke_actor_idx on public.smoke_test_runs(tenant_id,initiated_by);
create table public.smoke_test_steps(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,run_id uuid not null,test_name text not null,expected_result text not null,actual_result text not null,status text not null check(status in ('passed','failed','blocked','pending')),error_code text,corrective_action text,log_reference text,verified_at timestamptz not null default now(),created_at timestamptz not null default now(),foreign key(tenant_id,run_id) references public.smoke_test_runs(tenant_id,id));
create index smoke_steps_idx on public.smoke_test_steps(tenant_id,run_id);
alter table public.settings add column publisher_filters jsonb not null default '{"minimum_dr":30,"maximum_spam":5,"minimum_traffic":1000}';

do $$ declare t text;begin
 foreach t in array array['permissions','roles','role_permissions'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy authenticated_read on public.%I for select to authenticated using(auth.uid() is not null)',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;
 foreach t in array array['user_permissions','tasks','seo_article_versions','publication_reports','publication_report_items','shared_reports','publisher_catalog','publisher_metric_observations','smoke_test_runs','smoke_test_steps'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;
end $$;
create policy permission_read on public.user_permissions for select to authenticated using(tenant_id=private.tenant_id() and (user_id=auth.uid() or private.has_permission('users.read')));
create policy tasks_read on public.tasks for select to authenticated using(tenant_id=private.tenant_id() and private.has_permission('tasks.read') and (assigned_to=auth.uid() or created_by=auth.uid() or private.has_permission('tasks.manage')));
create policy versions_read on public.seo_article_versions for select to authenticated using(private.can_read_article(article_id));
create policy reports_read on public.publication_reports for select to authenticated using(private.has_permission('reports.view') and private.can_read_campaign(campaign_id));
create policy report_items_read on public.publication_report_items for select to authenticated using(exists(select 1 from public.publication_reports r where r.id=report_id and private.can_read_campaign(r.campaign_id) and private.has_permission('reports.view')));
create policy shared_reports_read on public.shared_reports for select to authenticated using(tenant_id=private.tenant_id() and private.has_permission('reports.share') and exists(select 1 from public.publication_reports r where r.id=report_id and private.can_read_campaign(r.campaign_id)));
create policy prospects_read on public.publisher_catalog for select to authenticated using(tenant_id=private.tenant_id() and private.has_permission('publishers.research'));
create policy prospect_metrics_read on public.publisher_metric_observations for select to authenticated using(tenant_id=private.tenant_id() and private.has_permission('publishers.research'));
create policy smoke_read on public.smoke_test_runs for select to authenticated using(tenant_id=private.tenant_id() and (initiated_by=auth.uid() or private.has_permission('campaigns.read_all')));
create policy smoke_steps_read on public.smoke_test_steps for select to authenticated using(exists(select 1 from public.smoke_test_runs s where s.id=run_id and (s.initiated_by=auth.uid() or private.has_permission('campaigns.read_all')) and s.tenant_id=private.tenant_id()));
-- Legacy website RPC role checks now include the trusted SEO-manager role; central API permissions still apply.
do $$ declare f record;d text;begin for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('reserve_connection_version','enqueue_browser_check','import_website_inventory') loop d:=pg_get_functiondef(f.sig);d:=replace(d,'''admin'',''super_admin''','''admin'',''super_admin'',''seo_manager''');d:=replace(d,'''super_admin'',''admin''','''super_admin'',''admin'',''seo_manager''');execute d;end loop;end $$;
revoke all on function private.snapshot_article(),private.sync_publication_report() from public,anon,authenticated;
revoke all on function public.effective_permissions(uuid),public.validate_actor_session(uuid,uuid,boolean) from public,anon,authenticated;grant execute on function public.effective_permissions(uuid),public.validate_actor_session(uuid,uuid,boolean) to service_role;

create function public.update_employee_access(p_actor uuid,p_employee uuid,p_role text,p_active boolean,p_name text,p_department text,p_permissions jsonb) returns void language plpgsql set search_path='' as $$
declare a public.profiles;e public.profiles;pair record;begin
 select * into a from public.profiles where id=p_actor and active;select * into e from public.profiles where id=p_employee and tenant_id=a.tenant_id for update;
 if not private.actor_permission(p_actor,'users.update') or e.id is null or e.id=a.id or e.role='super_admin' or p_role='super_admin' then raise exception 'Employee access update denied';end if;
 if (e.role='admin' or p_role='admin') and a.role<>'super_admin' then raise exception 'Only the owner may manage administrators';end if;
 if e.active<>p_active and not private.actor_permission(p_actor,'users.disable') then raise exception 'Account status permission required';end if;
 if p_permissions is not null then
  for pair in select * from jsonb_each(p_permissions) loop
   if jsonb_typeof(pair.value)<>'boolean' or not exists(select 1 from public.permissions where key=pair.key) or not private.actor_permission(p_actor,pair.key) or (a.role<>'super_admin' and pair.key like 'users.%') then raise exception 'Permission grant denied';end if;
  end loop;
  delete from public.user_permissions where user_id=e.id;
  insert into public.user_permissions(tenant_id,user_id,permission_key,allowed) select a.tenant_id,e.id,key,(value::text)::boolean from jsonb_each(p_permissions);
 end if;
 update public.profiles set role=p_role,active=p_active,full_name=p_name,department=p_department,can_publish=p_role in ('admin','seo_manager','publishing_operator'),min_session_created_at=clock_timestamp(),updated_at=clock_timestamp() where id=e.id;
end $$;
create function public.complete_employee_password_change(p_actor uuid) returns void language plpgsql set search_path='' as $$ begin update public.profiles set password_change_required=false,min_session_created_at=clock_timestamp(),updated_at=clock_timestamp() where id=p_actor and active and password_change_required;if not found then raise exception 'No required credential change is pending';end if;end $$;
create function public.accept_seo_version(p_actor uuid,p_version uuid,p_content text,p_metadata jsonb) returns uuid language plpgsql set search_path='' as $$
declare a public.profiles;v public.seo_article_versions;r public.articles;begin
 select * into a from public.profiles where id=p_actor and active;select * into v from public.seo_article_versions where id=p_version and tenant_id=a.tenant_id;select * into r from public.articles where id=v.article_id and tenant_id=a.tenant_id for update;
 if r.id is null or not private.actor_permission(p_actor,'articles.edit') or (not private.actor_permission(p_actor,'articles.read_all') and r.owner_id<>a.id and r.assigned_to is distinct from a.id) then raise exception 'Article edit denied';end if;
 if v.source_updated_at is distinct from r.updated_at then raise exception 'The source article changed. Generate or review a fresh proposal';end if;
 update public.articles set content=p_content,title=p_metadata->>'title',meta_title=coalesce(p_metadata->>'meta_title',''),meta_description=coalesce(p_metadata->>'meta_description',''),slug=coalesce(p_metadata->>'slug',''),focus_keyword=coalesce(p_metadata->>'primary_keyword',''),category=coalesce(p_metadata->>'category',''),tags=array(select jsonb_array_elements_text(coalesce(p_metadata->'tags','[]'))),status='draft',approved_by=null,approved_at=null,approved_version_id=null,updated_at=clock_timestamp() where id=r.id;
 update public.articles set current_version_id=v.id where id=r.id;update public.seo_article_versions set optimized_content=p_content,seo_data=p_metadata,status='accepted' where id=v.id;return r.id;
end $$;
create function public.approve_article_version(p_actor uuid,p_article uuid,p_version uuid) returns void language plpgsql set search_path='' as $$
declare a public.profiles;r public.articles;v public.seo_article_versions;begin
 select * into a from public.profiles where id=p_actor and active;select * into r from public.articles where id=p_article and tenant_id=a.tenant_id for update;
 if r.id is null or not private.actor_permission(p_actor,'articles.approve') then raise exception 'Article approval denied';end if;
 select * into v from public.seo_article_versions where id=p_version and article_id=r.id and tenant_id=r.tenant_id;
 if v.id is null or r.current_version_id is distinct from v.id or v.optimized_content<>r.content then raise exception 'Approve the exact current article version';end if;
 update public.seo_article_versions set status='approved',approved_by=a.id,approved_at=clock_timestamp() where id=v.id;update public.articles set status='approved',approved_by=a.id,approved_at=clock_timestamp(),approved_version_id=v.id where id=r.id;
end $$;
-- Keep V4 atomic approval + campaign allocation, now with traceable version approval.
create or replace function public.approve_and_create_campaign(p_actor uuid,p_article uuid,p_version timestamptz,p_name text,p_sites uuid[],p_interval integer,p_start timestamptz,p_overrides jsonb,p_mode text) returns uuid language plpgsql set search_path='' as $$
declare a public.profiles;r public.articles;c uuid;begin
 select * into a from public.profiles where id=p_actor and active;if a.id is null or not private.actor_permission(p_actor,'campaigns.launch') then raise exception 'Campaign launch permission required';end if;
 select * into r from public.articles where id=p_article and tenant_id=a.tenant_id for update;if r.id is null then raise exception 'Article not found in this workspace';end if;
 if p_version is null or r.updated_at<>p_version then raise exception 'The article changed after review. Refresh and review it again';end if;
 if r.status<>'approved' then perform public.approve_article_version(p_actor,r.id,r.current_version_id);end if;
 c:=public.create_campaign(p_actor,p_article,p_name,p_sites,p_interval,p_start,p_overrides);update public.campaigns set selection_mode=p_mode where id=c;return c;
end $$;
alter table public.publication_report_items add column verification_attempts integer not null default 0,add column next_check_at timestamptz not null default now();
create function public.claim_report_verification() returns jsonb language plpgsql set search_path='' as $$ declare r public.publication_report_items;j public.publishing_jobs;c public.campaigns;begin
 update public.publication_report_items set check_status='queued',lease_token=null,lease_until=null where check_status='checking' and lease_until<now();
 select i.* into r from public.publication_report_items i join public.publishing_jobs p on p.id=i.job_id where i.check_status='queued' and p.status='published' and i.published_url is not null and i.next_check_at<=now() and i.verification_attempts<3 order by i.updated_at limit 1 for update of i skip locked;
 if r.id is null then return null;end if;update public.publication_report_items set check_status='checking',verification_attempts=verification_attempts+1,lease_token=gen_random_uuid(),lease_until=now()+interval '2 minutes' where id=r.id returning * into r;select * into j from public.publishing_jobs where id=r.job_id;select * into c from public.campaigns where id=j.campaign_id;return jsonb_build_object('item',to_jsonb(r),'job',to_jsonb(j),'article',c.article_snapshot||coalesce(j.overrides,'{}'));
end $$;
create function public.finish_report_verification(p_item uuid,p_token uuid,p_result jsonb) returns void language plpgsql set search_path='' as $$ declare r public.publication_report_items;begin
 select * into r from public.publication_report_items where id=p_item and lease_token=p_token and lease_until>now() and check_status='checking' for update;if r.id is null then raise exception 'Expired report verification lease';end if;
 update public.publication_report_items set verification_status=case when coalesce((p_result->>'verified')::boolean,false) then 'verified' when p_result->>'status' in ('unavailable','pending') then p_result->>'status' else 'pending' end,verified_at=clock_timestamp(),http_status=(p_result->>'http_status')::integer,page_title=left(p_result->>'page_title',500),verification_details=p_result,check_status=case when p_result->>'status'='pending' and verification_attempts<3 then 'queued' else 'complete' end,next_check_at=clock_timestamp()+interval '5 minutes',lease_token=null,lease_until=null,updated_at=clock_timestamp() where id=r.id;
 update public.publication_reports set last_verified_at=clock_timestamp() where id=r.report_id;
end $$;
-- Permission removal/suspension stops future claims owned by that account.
do $$ declare d text;needle text:='and w.status=''active'' and w.connection_status=''connected''';begin d:=pg_get_functiondef('public.claim_next_job(text,uuid)'::regprocedure);if position(needle in d)=0 then raise exception 'Inspect queue implementation before adding the campaign-owner gate';end if;execute replace(d,needle,'and private.actor_permission(c0.owner_id,''campaigns.launch'') and w.status=''active'' and w.connection_status=''connected''');end $$;
do $$ declare f record;begin for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('update_employee_access','complete_employee_password_change','accept_seo_version','approve_article_version','claim_report_verification','finish_report_verification') loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;end $$;
